CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE COLLATE NOCASE,password_hash TEXT NOT NULL,display_name TEXT NOT NULL,email_verified_at TEXT,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','suspended','pending')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE roles(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL,label TEXT NOT NULL);
CREATE TABLE permissions(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL,description TEXT NOT NULL);
CREATE TABLE role_permissions(role_id INTEGER NOT NULL REFERENCES roles(id) ON DELETE CASCADE,permission_id INTEGER NOT NULL REFERENCES permissions(id) ON DELETE CASCADE,PRIMARY KEY(role_id,permission_id));
CREATE TABLE user_roles(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,role_id INTEGER NOT NULL REFERENCES roles(id),assigned_by TEXT REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,role_id));
CREATE TABLE sessions(sid TEXT PRIMARY KEY,sess TEXT NOT NULL,expired TEXT NOT NULL);
CREATE TABLE donor_profiles(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,public_anonymous INTEGER NOT NULL DEFAULT 0,preferences_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE volunteer_profiles(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,location TEXT,skills TEXT,availability TEXT,interests TEXT,consent_at TEXT);
CREATE TABLE volunteer_applications(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),name TEXT NOT NULL,email TEXT NOT NULL,phone TEXT,location TEXT,skills TEXT,availability TEXT,interests TEXT,message TEXT,status TEXT NOT NULL DEFAULT 'submitted',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE help_requests(id TEXT PRIMARY KEY,name TEXT NOT NULL,contact TEXT NOT NULL,region TEXT,request_summary TEXT NOT NULL,consent_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'received',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE programmes(id TEXT PRIMARY KEY,slug TEXT UNIQUE NOT NULL,title TEXT NOT NULL,summary TEXT NOT NULL,body TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'pending_review',audience TEXT NOT NULL DEFAULT '',services TEXT NOT NULL DEFAULT '',eligibility TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE campaigns(id TEXT PRIMARY KEY,slug TEXT UNIQUE NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL,target_minor INTEGER,currency TEXT,deadline TEXT,status TEXT NOT NULL DEFAULT 'draft',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE donations(id TEXT PRIMARY KEY,donor_user_id TEXT REFERENCES users(id),email TEXT,amount_minor INTEGER NOT NULL CHECK(amount_minor>0),currency TEXT NOT NULL,campaign_id TEXT REFERENCES campaigns(id),programme_id TEXT REFERENCES programmes(id),anonymous INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'created',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE payment_transactions(id TEXT PRIMARY KEY,donation_id TEXT NOT NULL REFERENCES donations(id),provider TEXT NOT NULL,provider_reference TEXT UNIQUE,amount_minor INTEGER NOT NULL,currency TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'created',checkout_url TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE webhook_events(provider TEXT NOT NULL,event_id TEXT NOT NULL,received_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,processed_at TEXT,PRIMARY KEY(provider,event_id));
CREATE TABLE refunds(id TEXT PRIMARY KEY,donation_id TEXT NOT NULL REFERENCES donations(id),amount_minor INTEGER NOT NULL,currency TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'requested',requested_by TEXT REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE reconciliation_records(id TEXT PRIMARY KEY,transaction_id TEXT NOT NULL REFERENCES payment_transactions(id),actor_id TEXT NOT NULL REFERENCES users(id),outcome TEXT NOT NULL,note TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE news_posts(id TEXT PRIMARY KEY,slug TEXT UNIQUE NOT NULL,title TEXT NOT NULL,summary TEXT NOT NULL,body TEXT NOT NULL,author_id TEXT REFERENCES users(id),status TEXT NOT NULL DEFAULT 'draft',published_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE events(id TEXT PRIMARY KEY,slug TEXT UNIQUE NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL,starts_at TEXT NOT NULL,timezone TEXT NOT NULL,venue TEXT,status TEXT NOT NULL DEFAULT 'draft',countdown_enabled INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE timeline_entries(id TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL,occurred_on TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft');
CREATE TABLE gallery_albums(id TEXT PRIMARY KEY,title TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft');
CREATE TABLE media_assets(id TEXT PRIMARY KEY,album_id TEXT REFERENCES gallery_albums(id),storage_name TEXT NOT NULL,alt_text TEXT NOT NULL,caption TEXT,moderation_status TEXT NOT NULL DEFAULT 'pending');
CREATE TABLE team_members(id TEXT PRIMARY KEY,name TEXT NOT NULL,position TEXT NOT NULL,biography TEXT NOT NULL DEFAULT '',image_path TEXT,status TEXT NOT NULL DEFAULT 'draft');
CREATE TABLE partners(id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT,status TEXT NOT NULL DEFAULT 'draft');
CREATE TABLE contact_messages(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL,subject TEXT NOT NULL,message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'received',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE newsletter_subscribers(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL COLLATE NOCASE,consent_at TEXT NOT NULL,unsubscribed_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE faqs(id TEXT PRIMARY KEY,question TEXT NOT NULL,answer TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'draft');
CREATE TABLE homepage_sections(id TEXT PRIMARY KEY,section_key TEXT UNIQUE NOT NULL,content_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',updated_by TEXT REFERENCES users(id),updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE service_cards(id TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL,image_path TEXT,alt_text TEXT NOT NULL DEFAULT '',sort_order INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'draft');
CREATE TABLE impact_metrics(id TEXT PRIMARY KEY,label TEXT NOT NULL,value TEXT NOT NULL,evidence_note TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending_review',approved_by TEXT REFERENCES users(id),approved_at TEXT);
CREATE TABLE site_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_by TEXT REFERENCES users(id),updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE policies_documents(id TEXT PRIMARY KEY,slug TEXT UNIQUE NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',reviewed_at TEXT);
CREATE TABLE audit_logs(id TEXT PRIMARY KEY,actor_id TEXT REFERENCES users(id),action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT,metadata_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_donations_status_date ON donations(status,created_at);CREATE INDEX idx_events_status_date ON events(status,starts_at);CREATE INDEX idx_news_publication ON news_posts(status,published_at);CREATE INDEX idx_audit_entity ON audit_logs(entity_type,entity_id,created_at);
